{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "Subnetwork does not have flow logs enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "Flow logs are not enabled for this subnetwork, potentially hindering network traffic monitoring and debugging."
    }
  ],
  "patched_code": "resource \"google_compute_subnetwork\" \"data_subnet\" {\n  name                     = \"hipaa-compliant-patient-portal-subnet-data\"\n  ip_cidr_range            = \"10.0.3.0/24\"\n  region                   = var.region\n  network                  = google_compute_network.hipaa_vpc.id\n  private_ip_google_access = true\n  log_config {\n    aggregation_interval = \"INTERVAL_5_SEC\"\n    flow_sampling        = 0.5\n    metadata             = \"INCLUDE_ALL_METADATA\"\n  }\n}",
  "fix_summary": "Enabled flow logs for the subnetwork with default log configuration settings."
}
